(()=>{document.body.style.margin='0';const out=[];for(const family of ['Arial','Times New Roman'])for(const size of [13,14,17])for(const text of ['vvvv sssss ttttt tttt','alpha beta gamma delta','The quick brown fox']){const e=document.createElement('div');e.style.cssText='position:absolute;left:10px;top:20px;padding:4.4545px;border:2px solid;font:'+size+'px "'+family+'"';e.textContent=text;document.body.append(e);const r=e.getBoundingClientRect();out.push({family,size,text,width:r.width,height:r.height});e.remove()}return out})()